<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($title)?></title><link rel="stylesheet" href="<?=base_url('styles.css')?>"><style>body{background:#090b0d;color:#eee}.wrap{max-width:1000px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:15px}.btn{padding:10px 14px;border:1px solid #444;border-radius:9px;color:#e8d4ac;text-decoration:none}.primary{background:#c6a66e;color:#111}.card{margin-top:18px;padding:22px;border:1px solid #292929;border-radius:18px;background:#111416}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #2b2b2b;text-align:left}.muted{color:#999;font-size:11px}@media(max-width:700px){.top,.grid{display:grid}}</style></head><body><div class="wrap"><div class="top"><div><div class="muted">LEX FACTUM &amp; PARTNERS · CLIENT PORTAL</div><h1 style="font:500 35px Georgia,serif"><?=esc($invoice['invoice_no'])?></h1></div><div><a class="btn" href="<?=site_url('my-invoices')?>">← My Invoices</a> <a class="btn primary" target="_blank" href="<?=site_url('my-invoices/'.$invoice['id'].'/print?autoprint=1')?>">Print / Save PDF</a></div></div><div class="grid"><div class="card"><div class="muted">INVOICE DATE</div><h3><?=date('d M Y',strtotime($invoice['invoice_date']))?></h3><div class="muted">MATTER</div><p><?=esc($invoice['case_reference']?:'General professional services')?></p></div><div class="card"><div class="muted">AMOUNT</div><h2>₹ <?=number_format($invoice['total'],2)?></h2><div class="muted">STATUS</div><p><b><?=esc($invoice['payment_status'])?></b></p></div></div><div class="card"><h2 style="font:500 24px Georgia,serif">Professional charges</h2><table class="table"><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr><?php foreach($items as $x):?><tr><td><?=nl2br(esc($x['description']))?></td><td><?=rtrim(rtrim(number_format($x['quantity'],2), '0'),'.')?></td><td>₹ <?=number_format($x['rate'],2)?></td><td>₹ <?=number_format($x['amount'],2)?></td></tr><?php endforeach;?></table></div></div></body></html>
